func save_game(path: String = SAVE_PATH) -> bool:
	if current_room == null:
		return false

	var rooms_data: Dictionary = {}
	for room_id in world.rooms:
		var room: Room = world.rooms[room_id]
		rooms_data[room_id] = {
			"items": room.items.duplicate(),
			"locked_exits": room.locked_exits.duplicate()
		}

	var data: Dictionary = {
		"current_room_id": current_room.id,
		"inventory": inventory.duplicate(),
		"rooms": rooms_data
	}

	var file := FileAccess.open(path, FileAccess.WRITE)
	if file == null:
		message_label.text = "Errore durante il salvataggio."
		return false

	file.store_string(JSON.stringify(data, "\t"))
	file.close()

	message_label.text = "Partita salvata."
	return true


func load_game(path: String = SAVE_PATH) -> bool:
	if not FileAccess.file_exists(path):
		message_label.text = "Nessun salvataggio trovato."
		return false

	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		message_label.text = "Impossibile aprire il file di salvataggio."
		return false

	var content := file.get_as_text()
	file.close()

	var parsed = JSON.parse_string(content)
	if not (parsed is Dictionary):
		message_label.text = "File di salvataggio non valido."
		return false

	var data: Dictionary = parsed
	if not data.has("current_room_id") or not data.has("inventory") or not data.has("rooms"):
		message_label.text = "Dati di salvataggio incompleti."
		return false

	# Ricarica il mondo base per ripristinare nomi, descrizioni e collegamenti
	if not world.load_file("res://adventure.json"):
		message_label.text = "Errore nel caricamento del mondo."
		return false

	# Ripristina lo stato modificato di ciascuna stanza
	var rooms_data: Dictionary = data["rooms"]
	for room_id in rooms_data:
		var r_state = rooms_data[room_id]
		if not (r_state is Dictionary):
			continue
		var room := world.get_room(str(room_id))
		if room != null:
			if r_state.has("items") and r_state["items"] is Array:
				var items_list: Array[String] = []
				for item in r_state["items"]:
					items_list.append(str(item))
				room.items = items_list
			if r_state.has("locked_exits") and r_state["locked_exits"] is Dictionary:
				room.locked_exits = r_state["locked_exits"].duplicate()

	# Ripristina l'inventario
	var new_inv: Array[String] = []
	for item in data["inventory"]:
		new_inv.append(str(item))
	inventory = new_inv

	# Ripristina la stanza corrente
	var target_room := world.get_room(str(data["current_room_id"]))
	if target_room != null:
		current_room = target_room

	message_label.text = "Partita caricata."
	_update_inventory_ui()
	_update_room_ui()
	return true


func _on_save_pressed() -> void:
	save_game()


func _on_load_pressed() -> void:
	load_game()

